"""Transcribed from the seven supplied PDFs; letters retain source ordering.
Each question has one primary topic so frequency counts total exactly 84.
Explanations are worked solutions, not quotations from the answer-only keys.
"""
import json, base64
from pathlib import Path

ROOT=Path(__file__).resolve().parent
KEYS={'f2022':'ECB EADBEBCAE'.replace(' ',''),'f2023':'AAAEBECDDBAB','f2024':'CD ADEBB ADEBA'.replace(' ',''),'s2022':'CABDBDACFEDC','s2023':'BAADADBCECED','s2024':'EBAEBEEAAEAC','s2025':'ECBFB DACFEAC'.replace(' ','')}
VERSIONS={'f2022':'01','f2023':'1111','f2024':'01','s2022':'1010','s2023':'01','s2024':'11','s2025':'1010'}
TOPICS={'curves':'Curve geometry','surfaces':'Surfaces & level curves','geometry':'Lines & planes','limits':'Multivariable limits','gradient':'Gradients & direction','partials':'Partial derivatives','chain':'Chain & implicit rules','tangent':'Tangent planes','extrema':'Critical points & extrema','motion':'Motion & integration','vectors':'Vector algebra'}
BANK=[]
def add(exam,n,topic,stem,choices,explanation,note=None,figure=None):
    page=n+2 if exam in ['f2022','f2024'] else n+1 if exam=='s2024' else (n+1)//2+1
    opts=choices.split('|')
    answer=ord(KEYS[exam][n-1])-65
    assert 0<=answer<len(opts),(exam,n,answer)
    BANK.append(dict(id=f'{exam}-{n}',exam=exam,number=n,page=page,version=VERSIONS[exam],topic=topic,stem=stem,options=opts,answer=answer,explanation=explanation,note=note,figure=figure))

add('f2022',1,'curves','The curves r₁(t) = ⟨t, t², 1⟩ and r₂(t) = ⟨sin t, sin 2t, 1⟩ intersect at (0, 0, 1) at an angle θ. Find cos θ.','1/√6|1/5|1/√3|1/3|1/√5','At t = 0, the tangent vectors are r₁′ = ⟨1, 0, 0⟩ and r₂′ = ⟨1, 2, 0⟩. Their dot product is 1 and their lengths are 1 and √5, so cos θ = 1/√5.')
add('f2022',2,'surfaces','Identify the surface x² − y² − 4x + z² = 4.','Hyperboloid of two sheets|Hyperbolic paraboloid|Hyperboloid of one sheet|Ellipsoid|Cone','Complete the square: (x − 2)² + z² − y² = 8. With two positive squared terms and one negative squared term equal to a positive constant, this is a hyperboloid of one sheet, with axis parallel to y.')
add('f2022',3,'motion','A particle has acceleration a(t) = 6t j + 2k, initial position r(0) = j, and initial velocity v(0) = i − j. Find the distance from its position at t = 1 to (2, 2, 3).','3|√6|√7|1|2','Integrating with the initial conditions gives v(t) = ⟨1, 3t² − 1, 2t⟩ and r(t) = ⟨t, t³ − t + 1, t²⟩. Thus r(1) = (1, 1, 1), and the distance to (2, 2, 3) is √(1 + 1 + 4) = √6.')
add('f2022',4,'geometry','Determine b so that the line (x + 7)/4 = (y + 2)/b = (z − 1)/2 is parallel to the plane 3x − 2y + 2z = 14.','1|3|6|7|8','The direction vector ⟨4, b, 2⟩ must be perpendicular to the plane normal ⟨3, −2, 2⟩. Set their dot product to zero: 12 − 2b + 4 = 0, so b = 8.')
add('f2022',5,'curves','Let r(t) = ⟨5 sin t, 3 cos t, 4 cos t⟩. Compute the curvature κ(π/2).','1/5|√2|√2/5|5|5/√2','The sine and cosine coefficient vectors are orthogonal and both have length 5, so the curve is a circle of radius 5 and curvature 1/5. Equivalently, |r′| = 5 and |r′ × r″| = 25, giving κ = 25/125.')
add('f2022',6,'surfaces','The level curves of f(x, y) = √(9x² + 16y² + 25) − 4y are:','Circles|Hyperbolas|Ellipses|Parabolas|Lines','Set f = c: √(9x² + 16y² + 25) = c + 4y. Squaring yields 9x² + 25 = c² + 8cy. The function is positive, so every nonempty level has c > 0 and is a parabola.')
add('f2022',7,'partials','Let f(x, y, z) = e<sup>xy²</sup> + sin(x³ + y³) + ln(y⁷) + tan(9x³). Compute f<sub>xyz</sub>(0, 3, 7).','6|0|3|7|9','The function has no dependence on z. Any partial derivative involving differentiation with respect to z is therefore zero wherever the function is defined, including the stated point.')
add('f2022',8,'limits','Evaluate lim<sub>(x,y)→(0,0)</sub> [1 − cos(x² + 3y²)] / (7x² + 21y²).','1/21|1|√1/3|1/7|0','Let u = x² + 3y². The expression is (1 − cos u)/(7u). Since 1 − cos u is asymptotic to u²/2, the quotient tends to 0.')
add('f2022',9,'chain','For (x² + y²)³ = 8x²y², find y′ at (−1, 1).','−1|1|0|Does not exist|1/2','Implicit differentiation gives 6(x² + y²)²(x + yy′) = 16xy² + 16x²yy′. At (−1, 1), this becomes 24(−1 + y′) = −16 + 16y′, hence y′ = 1.')
add('f2022',10,'gradient','Find the directional derivative of f(x, y) = xy + x³ at (1, 2) in the direction ⟨1, −1⟩.','4|2√3|2√2|6|3√2','The gradient is ⟨y + 3x², x⟩, giving ⟨5, 1⟩ at (1, 2). Normalize the direction to ⟨1, −1⟩/√2. The dot product is (5 − 1)/√2 = 2√2.')
add('f2022',11,'tangent','On the surface z = 3 − x² − y² + 6y, find the point where the tangent plane is horizontal.','(0, 3, 12)|(1, 2, 3)|(3, 2, 3)|(12, 3, 0)|(3, 2, −3)','A horizontal tangent plane requires fₓ = −2x = 0 and fᵧ = −2y + 6 = 0. Thus x = 0 and y = 3, which gives z = 3 − 9 + 18 = 12.')
add('f2022',12,'extrema','Find the relative extremum of f(x, y) = −x³ + 4xy − 2y² + 1.','(2/3, −2/3), local maximum|(2/3, −2/3), local minimum|(4/3, 4/3), local minimum|(2/3, −4/3), local maximum|(4/3, 4/3), local maximum','The critical equations are −3x² + 4y = 0 and 4x − 4y = 0, giving (0, 0) and (4/3, 4/3). The Hessian determinant is D = 24x − 16. At (0, 0), D < 0, so it is a saddle. At (4/3, 4/3), D = 16 > 0 and fₓₓ = −8 < 0, so there is a local maximum.')

add('f2023',1,'motion','A rocket has acceleration a(t) = ⟨cos t, 4, e<sup>−t</sup>⟩, position r(0) = ⟨0, 0, 0⟩, and velocity v(0) = ⟨1, 2, 3⟩. Find r(2).','⟨3 − cos 2, 12, 7 + e<sup>−2</sup>⟩|⟨cos 2, 8, e<sup>−2</sup>⟩|⟨−cos 2, 8, 8 − e<sup>−2</sup>⟩|⟨1 − cos 2, 12, 7 + e<sup>−2</sup>⟩|⟨1 − cos 2, 12, 8 + e<sup>−2</sup>⟩','Integrate and apply v(0): v(t) = ⟨sin t + 1, 4t + 2, 4 − e<sup>−t</sup>⟩. Integrate again and use r(0): r(t) = ⟨1 − cos t + t, 2t² + 2t, 4t + e<sup>−t</sup> − 1⟩. Substitute t = 2.')
add('f2023',2,'curves','Let r(t) = ⟨√3 sin t, sin t, 2 cos t⟩. Compute κ(π/2).','1/2|1|2|√2/2|√3/2','The vectors ⟨√3, 1, 0⟩ and ⟨0, 0, 2⟩ are orthogonal and both have length 2. The curve is a circle of radius 2, so its curvature is 1/2.')
add('f2023',3,'gradient','For f(x, y) = 25 − x² − y², find the unit direction of steepest descent at (3, −4).','⟨3/5, −4/5⟩|⟨−√2/2, √2/2⟩|⟨√2/2, √2/2⟩|⟨√3/2, −1/2⟩|⟨−3/5, 4/5⟩','At (3, −4), ∇f = ⟨−6, 8⟩ and |∇f| = 10. Steepest descent is in the negative gradient direction: −∇f/|∇f| = ⟨3/5, −4/5⟩.')
add('f2023',4,'geometry','Determine a so that the line (x − 3)/a = (y + 5)/2 = (z + 1)/4 is parallel to the plane 2x + 3y − 5z = 14.','5|3|−14|−4|7','The line direction ⟨a, 2, 4⟩ must be perpendicular to the plane normal ⟨2, 3, −5⟩. Thus 2a + 6 − 20 = 0, so a = 7.')
add('f2023',5,'chain','Suppose fₓ = −4/x⁵ and fᵧ = 6y − 2, with x = r cos θ and y = r sin θ. Find ∂f/∂r at (r, θ) = (1, π).','−2|−4|−8|−6|0','Use fᵣ = fₓ cos θ + fᵧ sin θ. Here x = −1, y = 0, fₓ = 4, cos π = −1, and sin π = 0, so fᵣ = −4.')
add('f2023',6,'surfaces','Which vector-valued function could describe the graph shown?','r(t) = ⟨t cos t, 3, sin t⟩|r(t) = ⟨cos t, sin t, 2t⟩|r(t) = ⟨eᵗ, eᵗ, 1⟩|r(t) = ⟨2 cos t, √2 sin t, √2 sin t⟩|r(t) = ⟨t cos t, t sin t, 5⟩','The graph spirals outward in a horizontal plane. For ⟨t cos t, t sin t, 5⟩, z is fixed and the distance from the z-axis is |t|, so the radius grows as the curve winds around that axis.',figure='spiral')
add('f2023',7,'extrema','The point (0, 0) is a critical point of f(x, y) = cos x (2 + x²) − y³. What does the second derivative test tell us there?','It is a local minimum.|It is either a local maximum or a local minimum.|The test is inconclusive.|It is a local maximum.|It is a saddle point.','At (0, 0), fₓₓ = 0, fᵧᵧ = 0, and fₓᵧ = 0, so D = 0. The second derivative test is inconclusive. Although the −y³ term changes sign around the point, the question asks specifically what the test establishes.')
add('f2023',8,'tangent','Find the tangent plane to x² − y²/16 − z² = 3 at (2, 4, 0).','8x + y = 12|4x − y = 4|z = 0|8x − y = 12|2√3 x = 0','For F = x² − y²/16 − z² − 3, the normal is ∇F(2, 4, 0) = ⟨4, −1/2, 0⟩. Thus 4(x − 2) − (y − 4)/2 = 0, or 8x − y = 12.')
add('f2023',9,'partials','For f(x, y) = ln(x² + 4y² + 4), compute f<sub>yx</sub>(2, 1).','−32/81|−16 ln 81|−16/9|−2/9|−2/81','First fᵧ = 8y/(x² + 4y² + 4). Differentiate with respect to x: fᵧₓ = −16xy/(x² + 4y² + 4)². At (2, 1), this is −32/144 = −2/9.')
add('f2023',10,'surfaces','Identify the surface x² − y² − 4x + z² = 4.','Ellipsoid|Hyperboloid of one sheet|Hyperboloid of two sheets|Cone|Hyperbolic paraboloid','Complete the square to get (x − 2)² + z² − y² = 8. Two positive squares and one negative square equal a positive constant: a hyperboloid of one sheet.')
add('f2023',11,'limits','Evaluate lim<sub>(x,y)→(0,0)</sub> (e<sup>x+y</sup> − 1)/(2x − 2y).','The limit does not exist.|0|1|2|1/2','Along y = 0, the limit is 1/2. Along x = 0, it is −1/2. Both paths lie in the domain away from the origin, and their limits disagree, so the two-variable limit does not exist.')
add('f2023',12,'geometry','The line through (5, 1, 0) and (0, 2, 1) intersects x + y + z = 9 at which point?','(12, 0, −3)|(10, 0, −1)|(3, 5, 1)|(2, −1, 8)|(−1, 12, −2)','Parameterize the line as ⟨5, 1, 0⟩ + t⟨−5, 1, 1⟩. Substitution into the plane gives 6 − 3t = 9, so t = −1 and the intersection is (10, 0, −1).')

add('f2024',1,'geometry','The line through (2, 2, 2) and (3, 2, 1) intersects 2x + y + z = 7 at which point?','(1, 1, 4)|(1, 3, 2)|(1, 2, 3)|(0, 4, 3)|(2, −1, 4)','Write r(t) = ⟨2 + t, 2, 2 − t⟩. The plane equation becomes 8 + t = 7, so t = −1, giving (1, 2, 3).')
add('f2024',2,'surfaces','Identify the surface x² + 2x + y² − 4y − z² = −4.','Elliptic cone|Hyperboloid of two sheets|Hyperbolic paraboloid|Hyperboloid of one sheet|Ellipsoid','Completing both squares gives (x + 1)² + (y − 2)² − z² = 1. The two positive squared terms and one negative squared term identify a hyperboloid of one sheet.')
add('f2024',3,'geometry','For what value of a do r(t) = ⟨1 + t, t, 1 + t⟩ and R(s) = ⟨2 − s, s + 1, 2s + a⟩ intersect at one point?','2|0|1|−2|−1','Equate the first two coordinates: t + s = 1 and t = s + 1, so s = 0 and t = 1. Equating the third coordinates then gives 2 = a.')
add('f2024',4,'surfaces','The nonempty level curves of f(x, y) = e<sup>x²+y²−y</sup> are:','Non-circular ellipses|Parabolas|Hyperbolas|Circles|Lines','For a level c > 0, take logarithms and complete the square: x² + (y − 1/2)² = ln c + 1/4. Positive radii give circles. At c = e<sup>−1/4</sup>, the level degenerates to the single point (0, 1/2).','The key selects D. Strictly, the minimum level is a single point (a degenerate circle); the other nonempty levels are circles.')
add('f2024',5,'limits','Evaluate lim<sub>(x,y)→(0,0)</sub> [2x⁴ − 2y⁴ + sin(x² + y²)]/(x² + y²).','Does not exist|2|3|4|1','Factor x⁴ − y⁴ = (x² − y²)(x² + y²). The expression becomes 2(x² − y²) + sin u/u with u = x² + y². The first term tends to 0 and the second to 1.')
add('f2024',6,'chain','If yz³ = x + y + z, use implicit differentiation to find ∂z/∂x at (1, 0, −1), holding y constant.','−2|−1|0|1|2','Differentiate with y fixed: 3yz²zₓ = 1 + zₓ. Thus zₓ = 1/(3yz² − 1). At y = 0, this is −1.')
add('f2024',7,'curves','Find the arc length of r(t) = ⟨2 cos t + 2 sin t, 5, 2 cos t − 2 sin t⟩ for π ≤ t ≤ 2π.','π|√8 π|√8|2√8 π|2π','The derivative is ⟨−2 sin t + 2 cos t, 0, −2 sin t − 2 cos t⟩. Its squared norm is 8, so the speed is √8. Multiply by the interval length π to get √8 π.')
add('f2024',8,'curves','Find the curvature κ(t) of r(t) = ⟨cos t, sin t, 2t⟩.','1/5|5|sin²t|1|5√5','Here |r′| = √5, r″ = ⟨−cos t, −sin t, 0⟩, and |r′ × r″| = √5. Therefore κ = |r′ × r″|/|r′|³ = √5/(5√5) = 1/5.')
add('f2024',9,'motion','A particle has velocity v(t) = ⟨1, 2t, 3t²⟩ and passes through (4, −1, 5) at t = 0. Find its position r(t).','⟨5, 2t − 1, 3t³ + 5⟩|⟨t − 4, t² + 1, t³ − 5⟩|⟨t, t², t³⟩|⟨t + 4, t² − 1, t³ + 5⟩|⟨−3, 2t + 1, 3t³ − 5⟩','Integrate each component to get ⟨t + C₁, t² + C₂, t³ + C₃⟩. The initial position sets the constants to 4, −1, and 5.')
add('f2024',10,'gradient','Find the directional derivative of f(x, y, z) = xe<sup>yz</sup> at (0, 1, −1) in the direction ⟨1, 1, 1⟩.','3e|e/√3|1/e|e√3|1/(√3 e)','The gradient is ⟨e<sup>yz</sup>, xze<sup>yz</sup>, xye<sup>yz</sup>⟩, which becomes ⟨1/e, 0, 0⟩. Dot it with the unit direction ⟨1, 1, 1⟩/√3 to obtain 1/(√3 e).')
add('f2024',11,'geometry','Find a plane through (1, 0, 1) parallel to both ⟨1, 1, 2⟩ and ⟨−1, 0, 1⟩.','x − 3y + z = 0|x − 3y + z = 2|x + 3y + z = 2|x + 3y + z = 7|x + z = 0','A normal is the cross product ⟨1, 1, 2⟩ × ⟨−1, 0, 1⟩ = ⟨1, −3, 1⟩. Through (1, 0, 1), the equation is (x − 1) − 3y + (z − 1) = 0.')
add('f2024',12,'extrema','Find the critical points of f(x, y) = x²y + y + 2y².','(0, −1/4)|(1/4, 1/4)|(1/4, 0)|There are no critical points.|(0, 1)','Set fₓ = 2xy = 0 and fᵧ = x² + 1 + 4y = 0. If y = 0, the second equation has no real solution. Thus x = 0, and y = −1/4 is the only critical point.')

add('s2022',1,'tangent','Find the plane tangent to z² = 2xy at (1, 2, −2).','2x + y − 2z = 8|x + 2y − 2z = 9|2x + y + 2z = 0|4x + 2y − z = 10|x + 2y + 2z = 1|4x + 2y + z = 6','Use F = 2xy − z². The gradient at the point is ⟨4, 2, 4⟩, proportional to ⟨2, 1, 2⟩. Thus 2(x − 1) + (y − 2) + 2(z + 2) = 0, or 2x + y + 2z = 0.')
add('s2022',2,'extrema','Find the absolute maximum M and minimum m of f(x, y) = x² + y² − 4y + 4 on the disk x² + y² ≤ 16.','M = 36, m = 0|M = 36, m = 4|M = 28, m = 2|M = 28, m = 0|M = 28, m = 4|M = 36, m = 2','Rewrite f = x² + (y − 2)², the squared distance to (0, 2). That point lies inside the radius-4 disk, so the minimum is 0. The farthest point is (0, −4), at distance 6, so the maximum is 36.')
add('s2022',3,'limits','For lim<sub>(x,y)→(0,0)</sub> xy/(x² + y²), which statement is true?','The limit does not exist because the limit along y = x does not exist.|The limit does not exist, even though the limits along both coordinate axes are 0.|The limit does not exist because the two coordinate-axis limits are different.|The limit is 0 along every path.|The limit is 0 because the limit along y = x is 0.|The limit is 0 even though the two coordinate-axis limits are different.','Along either coordinate axis, the expression is 0. Along y = x, it is 1/2 for every nonzero x. These differing path limits prove the full limit does not exist. Agreement on the axes alone is not enough.')
add('s2022',4,'surfaces','Which surface does NOT contain the curve r(t) = ⟨cos t, −cos t, sin t⟩?','Plane: x + y = 0|Circular cylinder: y² + z² = 1|Ellipsoid: x²/2 + y²/2 + z² = 1|Circular cylinder: x² + y² = 1|Ellipsoid: x²/3 + 2y²/3 + z² = 1|Circular cylinder: x² + z² = 1','Substitution into x² + y² yields 2 cos²t, which is not identically 1. Each other equation simplifies to an identity using x = −y and cos²t + sin²t = 1.')
add('s2022',5,'surfaces','Suppose z = f(x, y) has the level curves shown. The graph of f could be which surface?','Plane|Hyperbolic paraboloid|Hyperboloid of two sheets|Ellipsoid|Elliptic paraboloid|Elliptic cone','A hyperbolic paraboloid such as z = x² − y² has hyperbolic level curves x² − y² = c. Positive and negative levels open in perpendicular directions, and the zero level gives two crossing lines, matching the figure.',figure='levels')
add('s2022',6,'motion','A ball starts at (0, h) with velocity ⟨10, 10⟩ and constant acceleration ⟨0, −g⟩, where g > 0. Find its location at maximum height.','((50 + 5√(100 + 2gh))/g, (10 + √(100 + 2gh))/g)|(100/g, (10 + √(100 + 2gh))/g)|((50 + 5√(100 + 2gh))/g, (100 + 3gh + 10√(100 + 2gh))/(4g))|(100/g, (50 + gh)/g)|(100/g, (100 + 3gh + 10√(100 + 2gh))/(4g))|((50 + 5√(100 + 2gh))/g, (50 + gh)/g)','The position is ⟨10t, h + 10t − gt²/2⟩. At maximum height, vertical velocity 10 − gt is zero, so t = 10/g. Substitution gives x = 100/g and y = h + 50/g = (50 + gh)/g.')
add('s2022',7,'geometry','The line ℓ passes through (1, 1, 1) and (2, 0, 1). Plane Q contains (0, 0, 0), (1, 2, 2), and (1, 0, 1). Find ℓ ∩ Q.','(0, 2, 1)|(−1, 4, 1)|(2, −2, 1)|(−2, 4, 1)|(4, −2, 1)|(3, −1, 1)','A normal to Q is ⟨1, 2, 2⟩ × ⟨1, 0, 1⟩ = ⟨2, 1, −2⟩, so Q is 2x + y − 2z = 0. On ℓ, r(t) = ⟨1 + t, 1 − t, 1⟩. Substitution gives 1 + t = 0, hence (0, 2, 1).')
add('s2022',8,'curves','Find the arc length function s(t) for r(t) = ⟨cos t + t sin t, sin t − t cos t, t²⟩, measured from (1, 0, 0) in the positive orientation (t ≥ 0).','[(1 + t²)<sup>3/2</sup> − 1]/3|∫₀ᵗ √(1 + u² + u⁴) du|(√5/2)t²|√5 t|(2√2/3)[(1 + t)<sup>3/2</sup> − 1]|[t√(1 + t²) + ln∣t + √(1 + t²)∣]/2','The starting point is r(0). Differentiate to get r′ = ⟨t cos t, t sin t, 2t⟩. For t ≥ 0 the speed is √5 t, so s(t) = ∫₀ᵗ √5 u du = (√5/2)t².')
add('s2022',9,'gradient','Find the directional derivative of f(x, y, z) = x²y + yz² at (1, 1, 1) in the direction (2/3)i + (1/3)j + (2/3)k.','3|8/3|8|2|10|10/3','The given direction already has length 1. The gradient is ⟨2xy, x² + z², 2yz⟩, equal to ⟨2, 2, 2⟩ at the point. Its dot product with ⟨2/3, 1/3, 2/3⟩ is 10/3.')
add('s2022',10,'surfaces','Which equation describes the pictured elliptic cone with vertex at the origin and opening along the x-axis?','y² − 4z² − 16x² = 1|y² + 4z² − 16x² = 1|y² + 4z² + 16x² = 1|y² − 4z² + 16x² = 0|y² + 4z² − 16x² = 0|y² − 4z² + 16x² = 1','A cone centered at the origin has a homogeneous quadratic equation with right-hand side 0. Opening along x means the x² term has the opposite sign to y² and z²: y² + 4z² = 16x². At each nonzero fixed x, the cross section is an ellipse.',figure='cone')
add('s2022',11,'extrema','Classify all critical points of f(x, y) = x³/3 − y³/3 + 2xy.','Two local maxima|One local maximum and one saddle point|One local maximum and one local minimum|One local minimum and one saddle point|Two local minima|Two saddle points','The critical equations x² + 2y = 0 and −y² + 2x = 0 give (0, 0) and (2, −2). The Hessian determinant is D = −4xy − 4. At the origin D = −4, a saddle. At (2, −2), D = 12 and fₓₓ = 4 > 0, a local minimum.')
add('s2022',12,'chain','Suppose fₓ(1, 1, 1) = 1, fᵧ(1, 1, 1) = 2, and f<sub>z</sub>(1, 1, 1) = 3. If x = t², y = t³, and z = t⁴, find df/dt at t = 1.','54|6|20|144|9|24','The chain rule gives df/dt = fₓ x′ + fᵧ y′ + f<sub>z</sub> z′. At t = 1, x′ = 2, y′ = 3, z′ = 4, so the result is 1·2 + 2·3 + 3·4 = 20.')

add('s2023',1,'geometry','Which vector is perpendicular to the plane through P(−1, −1, 1), Q(1, 2, 3), and R(3, 2, −1)?','⟨2, 4, −1⟩|⟨2, −2, 1⟩|⟨2, −1, 3⟩|⟨−1, 1, 3⟩|⟨−2, 1, 1⟩','The in-plane vectors are PQ = ⟨2, 3, 2⟩ and PR = ⟨4, 3, −2⟩. Their cross product is ⟨−12, 12, −6⟩ = −6⟨2, −2, 1⟩. Any nonzero multiple of that normal is perpendicular to the plane.')
add('s2023',2,'vectors','Which statements are true?<br>(I) The vector projection of u onto v equals the vector projection of u onto 2v.<br>(II) (i + j) × (i − j) = 0.<br>(III) (u × v) · v = 0.','I and III are true; II is false.|I and II are true; III is false.|II and III are true; I is false.|II is true; I and III are false.|All are true.','For a nonzero v, proj<sub>v</sub>u = [(u·v)/(v·v)]v is unchanged by replacing v with 2v. Statement II is false because (i + j) × (i − j) = −2k. Statement III is true because a cross product is perpendicular to each factor.','The original says “for every u and v” in statement I. Projection onto the zero vector is undefined; the keyed answer assumes v ≠ 0.')
add('s2023',3,'geometry','Plane K contains the x-axis and P(1, 2, 3). If it also contains (2, −4, a), find a + 4.','−2|−3|−4|−5|−6','A plane containing the entire x-axis has equation by + cz = 0. Passing through (1, 2, 3) gives 2b + 3c = 0, so one equation is 3y − 2z = 0. At (2, −4, a), −12 − 2a = 0, so a = −6 and a + 4 = −2.')
add('s2023',4,'surfaces','Identify the quadric surface 2x² + 3y² = 4x + 2z².','Hyperboloid of two sheets|Elliptic paraboloid|Hyperbolic paraboloid|Hyperboloid of one sheet|Elliptic cone','Complete the square and divide by 2: (x − 1)² + (3/2)y² − z² = 1. This has two positive squares and one negative square equal to 1, so it is a hyperboloid of one sheet.')
add('s2023',5,'curves','Find parametric equations for the tangent line to r(t) = ⟨t² + 3t + 2, eᵗ cos t, ln(t + 1)⟩ at (2, 1, 0).','x = 2 + 3t, y = 1 + t, z = t|x = 2t + 3, y = eᵗ(cos t − sin t), z = 1/(t + 1)|x = 2t + 3, y = 1 + t, z = 1|x = 3t, y = 2t, z = 1 + t|x = 2 − t, y = 1 + t, z = 3 − 3t','The point occurs at t = 0. The derivative there is r′(0) = ⟨3, 1, 1⟩. A tangent line is ⟨2, 1, 0⟩ + s⟨3, 1, 1⟩, which matches A after renaming s to t.')
add('s2023',6,'motion','A particle starts at the origin with initial velocity i + j − k and acceleration ti + j + tk. Find its position at t = 1.','(1/6)i + (1/2)j + (1/3)k|(7/6)i + (1/2)j − (5/6)k|i + j + k|(7/6)i + (3/2)j − (5/6)k|i + 2j − k','Integrate once: v(t) = ⟨t²/2 + 1, t + 1, t²/2 − 1⟩. Integrate from the origin: r(t) = ⟨t³/6 + t, t²/2 + t, t³/6 − t⟩. At t = 1 this gives ⟨7/6, 3/2, −5/6⟩.')
add('s2023',7,'surfaces','The nonempty level curves of f(x, y) = √(36 − 4x² − 9y²) are:','Sometimes parabolas and sometimes points|Sometimes ellipses and sometimes points|Sometimes hyperbolas and sometimes lines|Always parabolas|Always lines','A level c satisfies 4x² + 9y² = 36 − c², with 0 ≤ c ≤ 6. For 0 ≤ c < 6 this is an ellipse; for c = 6 it is the single point (0, 0).')
add('s2023',8,'curves','For r(t) = ⟨−13 cos t + 9, 5 sin t − 9, 12 sin t + 12⟩, compute κ(2π/3).','1/√5|13|1/13|5|0','Translation does not affect curvature. The coefficient vectors ⟨−13, 0, 0⟩ and ⟨0, 5, 12⟩ are orthogonal and both have length 13. The curve is a circle of radius 13, so κ = 1/13 at every point.')
add('s2023',9,'limits','How should f(0, 0) be defined to make f(x, y) = (x + y)²/(x² + y²) continuous at the origin?','f(0, 0) = 1|f(0, 0) = 2|f(0, 0) = 1/2|f(0, 0) = 0|No definition makes it continuous.','Along y = 0, the function equals 1. Along y = x, it equals 2. Since these path limits differ, no limit exists at the origin, and choosing a value there cannot make the function continuous.')
add('s2023',10,'partials','If f(x, y) = xy² + ye<sup>x²</sup> + 5, find f<sub>xx</sub>.','2ye<sup>x²</sup>|ye<sup>x²</sup>(1 + x²)|2ye<sup>x²</sup>(1 + 2x²)|2xe<sup>x²</sup> + y²|2xye<sup>x²</sup>','First fₓ = y² + 2xye<sup>x²</sup>. Differentiate again using the product and chain rules: fₓₓ = 2ye<sup>x²</sup> + 4x²ye<sup>x²</sup> = 2ye<sup>x²</sup>(1 + 2x²).')
add('s2023',11,'gradient','For f(x, y) = x³e<sup>−2y</sup>, find the directional derivative in the direction of greatest increase at (1, 0).','3i|3i − 2j|3|√5|√13','The gradient at (1, 0) is ⟨3, −2⟩. The maximum directional derivative is its magnitude, √(3² + (−2)²) = √13. The question asks for the rate, not the gradient vector.')
add('s2023',12,'chain','If u(p, q, r) = p² − q² − r, with p = xy, q = y², and r = xz, find ∂u/∂x at (x, y, z) = (1, 2, 5).','−1|9|13|3|0','Substitute first: u = x²y² − y⁴ − xz. Holding y and z constant gives uₓ = 2xy² − z. At (1, 2, 5), this is 8 − 5 = 3.')

add('s2024',1,'tangent','On 3x² − 12x + 5y³ + z + 6 = 0, find the point where the tangent plane is parallel to the xy-plane.','(2, 1, 1)|(3, 0, 11)|(3, 1, 7)|(1, 1, −2)|(2, 0, 6)','The surface normal is ⟨6x − 12, 15y², 1⟩. For a horizontal tangent plane, the first two components must be zero: x = 2 and y = 0. Substituting into the surface gives z = 6.')
add('s2024',2,'curves','Where is r(t) = ⟨ln(t²), √t, cos t⟩ continuous?','[0, ∞)|(0, ∞)|[0, 1)|(1, ∞)|(−∞, ∞)','Continuity requires all three components to be defined. ln(t²) requires t ≠ 0, while √t requires t ≥ 0. The common domain is (0, ∞), and all components are continuous there.')
add('s2024',3,'geometry','Find the line of intersection of x − 2y = 4 and x + y + z = 1.','⟨0, −2, 3⟩ + t⟨−2, −1, 3⟩|⟨0, 2, 3⟩ + t⟨−2, −1, 3⟩|⟨−2, −1, −1⟩ + t⟨0, 2, −1⟩|⟨−2, 1, −1⟩ + t⟨1, 1, 1⟩|⟨0, 2, −3⟩ + t⟨−2, 1, 3⟩','The point (0, −2, 3) satisfies both planes. The direction ⟨−2, −1, 3⟩ is perpendicular to both normals: its dot products with ⟨1, −2, 0⟩ and ⟨1, 1, 1⟩ are zero. Thus A lies in both planes for every t.')
add('s2024',4,'partials','Let f(x, y, z) = sin(zy) + e<sup>y²z³</sup> + sec(5y²) + ln(9z⁵). Compute f<sub>yxz</sub>(2, 1, π/2).','−2|1|−1|2|0','There is no x in the formula for f. A partial derivative that includes differentiation with respect to x is zero throughout the domain. Therefore f<sub>yxz</sub> at the stated point is 0.')
add('s2024',5,'curves','A particle has r(t) = ⟨4 cos t − 9, 3 cos t + 13, 5 sin t − 9⟩, t ≥ 0. Find t₂ − t₁ if it travels distance 40 between those times.','10|8|5|4|2','The velocity is ⟨−4 sin t, −3 sin t, 5 cos t⟩. Its norm is √(25 sin²t + 25 cos²t) = 5. Distance is therefore 5(t₂ − t₁), so t₂ − t₁ = 40/5 = 8.')
add('s2024',6,'vectors','Compute proj<sub>w</sub>u for w = ⟨−1, −1, 0⟩ and u = ⟨1, 2, 1⟩.','−(1/2)⟨−1, −1, 0⟩|(3/2)⟨1, 2, 1⟩|−(1/2)⟨1, 2, 1⟩|−(3/2)⟨1, 2, 1⟩|−(3/2)⟨−1, −1, 0⟩','Use proj<sub>w</sub>u = [(u·w)/(w·w)]w. Here u·w = −3 and w·w = 2, so the projection is −(3/2)w = ⟨3/2, 3/2, 0⟩.')
add('s2024',7,'chain','Suppose z(x, y) is defined implicitly by 4 cos(xy) = e<sup>3z</sup> − 1. Find ∂z/∂y at (3, π/2, 0).','4/3|4/3|−4|0|4','Differentiate with x held constant: −4x sin(xy) = 3e<sup>3z</sup>zᵧ. At the point, sin(3π/2) = −1 and e⁰ = 1, so 12 = 3zᵧ and zᵧ = 4.','Choices A and B are both printed as 4/3 in the supplied PDF. They are preserved here; the correct answer is E.')
add('s2024',8,'limits','If lim<sub>(x,y)→(0,0)</sub> [x⁶ − 8k(x³ + y³) − y⁶]/(x³ + y³) = 16, find k.','−2|4|2|−4|8','Factor x⁶ − y⁶ = (x³ − y³)(x³ + y³). At all points in the domain, the quotient becomes x³ − y³ − 8k. Its limit is −8k, so −8k = 16 gives k = −2.')
add('s2024',9,'extrema','Let M and m be the maximum and minimum of f(x, y) = x² + y² − 4y + 1 on x² + y² ≤ 9. Find M + m.','19|25|22|24|20','Write f = x² + (y − 2)² − 3. The center (0, 2) lies inside the radius-3 disk, so m = −3. The farthest point is (0, −3), giving M = 25 − 3 = 22. Therefore M + m = 19.')
add('s2024',10,'gradient','Find the directional derivative of f(x, y, z) = x⁴ + 3y² + cos z + 3 at (1, 1, π/4) in the direction ⟨−1, 1, 0⟩.','2√2|−√2|√2/2|5√2|√2','At the point, ∇f = ⟨4, 6, −√2/2⟩. The unit direction is ⟨−1, 1, 0⟩/√2. Their dot product is (−4 + 6)/√2 = √2.')
add('s2024',11,'surfaces','Identify the surface −x² − y²/4 + z²/7 = 1.','Hyperboloid of two sheets|Hyperboloid of one sheet|Hyperbolic paraboloid|Elliptic paraboloid|Elliptic cone','Exactly one squared term is positive and the right side is positive. Rearranging gives z²/7 = 1 + x² + y²/4, so |z| ≥ √7. The surface has two disconnected sheets along the z-axis.')
add('s2024',12,'curves','Let L be tangent to r(t) = ⟨3t − 1, t² + 2, t² − 3⟩ at (2, 3, −2). Where does L meet the xy-plane?','(1, −1, 0)|(1, 1, 0)|(5, 5, 0)|(−5, −5, 0)|(0, 0, 0)','The point occurs at t = 1 and r′(1) = ⟨3, 2, 2⟩. The tangent line is ⟨2, 3, −2⟩ + s⟨3, 2, 2⟩. The xy-plane has z = 0, so −2 + 2s = 0 gives s = 1 and point (5, 5, 0).')

add('s2025',1,'limits','Evaluate lim<sub>(x,y)→(1,−2)</sub> [y⁴ + x²y⁴ − 16 − 16x²]/(y² − 4), if it exists.','12|−8|0|8|16|The limit does not exist.','Factor the numerator as (1 + x²)(y⁴ − 16) = (1 + x²)(y² − 4)(y² + 4). On the domain, cancel y² − 4, then substitute (1, −2): (1 + 1)(4 + 4) = 16.')
add('s2025',2,'extrema','The points (0, 0) and (1, −3) are critical points of f(x, y) = x²y² + 6x²y − 2xy² − 12xy. Classify these two points.','Two local minima|Two local maxima|One local maximum and one saddle point|One local minimum and one saddle point|One local maximum and one local minimum|Two saddle points','The second derivatives are fₓₓ = 2y² + 12y, fᵧᵧ = 2x² − 4x, and fₓᵧ = 4xy + 12x − 4y − 12. At (0, 0), D = −144 < 0, so it is a saddle. At (1, −3), the diagonal entries are −18 and −2, and fₓᵧ = 0. Thus D = 36 > 0 with fₓₓ < 0: a local maximum.')
add('s2025',3,'surfaces','In planes parallel to and distinct from the xy-plane, the traces of z = x² − 4y² are:','Parabolas|Hyperbolas|Circles|Non-circular ellipses|Isolated points|Lines','Such a plane has z = c with c ≠ 0. The trace x² − 4y² = c is a hyperbola. Only the excluded plane z = 0 gives the pair of lines x = ±2y.')
add('s2025',4,'curves','Find a parameterization of the tangent line to r(t) = ⟨t cos(πt), t sin(πt), t²⟩ at r(1) = ⟨−1, 0, 1⟩.','ℓ(t) = ⟨−t, −πt, 2t⟩|ℓ(t) = ⟨−1 + πt, −t, 1 + 2t⟩|ℓ(t) = ⟨−1 − t, −π, 2 + t⟩|ℓ(t) = ⟨−1 + πt, −πt, 1 + 2t⟩|ℓ(t) = ⟨−πt, 0, 2t⟩|ℓ(t) = ⟨−1 − t, −πt, 1 + 2t⟩','Differentiate using the product rule: r′(1) = ⟨−1, −π, 2⟩. A tangent line is the base point plus a new parameter times this vector: ⟨−1, 0, 1⟩ + s⟨−1, −π, 2⟩.')
add('s2025',5,'gradient','Find the maximum rate of increase of f(x, y, z) = x ln∣y∣ + 1/z at (2, 1, 1).','√2|√5|√3|√6|1|2','The gradient is ⟨ln∣y∣, x/y, −1/z²⟩, equal to ⟨0, 2, −1⟩ at the point. The maximum rate of increase is |∇f| = √(0 + 4 + 1) = √5.')
add('s2025',6,'partials','Let f(x, y) = x<sup>y</sup> + y<sup>x</sup> for x ≥ 0 and y ≥ 0. Compute fₓ(2, 3).','21|18|9 ln 3 + 8 ln 2|12 + 9 ln 3|6 + 8 ln 2|17','Treat y as a constant. The derivative is fₓ = yx<sup>y−1</sup> + y<sup>x</sup> ln y. At (2, 3), this gives 3·2² + 3² ln 3 = 12 + 9 ln 3.')
add('s2025',7,'vectors','For vectors v and w in ℝ³, simplify v × (∥v∥w − v).','−∥v∥(w × v)|−∥v∥(w × v) − ∥v∥²|∥v∥(w × v) − v|∥v∥(w × v) − ∥v∥²|−∥v∥(w × v) − v|∥v∥(w × v)','Distribute the cross product: ∥v∥(v × w) − v × v. The second term is zero and v × w = −(w × v), giving −∥v∥(w × v).')
add('s2025',8,'curves','Find the arc length of r(t) = ⟨t², sin t − t cos t, cos t + t sin t⟩ from t = 0 to t = 1.','2√5|√5|√5/2|√3 − 1|√3|3','Differentiate: r′(t) = ⟨2t, t sin t, t cos t⟩. For 0 ≤ t ≤ 1, the speed is √(4t² + t²) = √5 t. Its integral from 0 to 1 is √5/2.')
add('s2025',9,'geometry','Find a parametrization of the line of intersection of x + 2y + 3z = 4 and −2x − y + z = 1.','⟨−2, −1, 1⟩ + t⟨1, 2, 3⟩|⟨3, −4, 3⟩ + t⟨−5, 5, −3⟩|⟨1, 2, 3⟩ + t⟨−2, −1, 1⟩|⟨5, −7, 3⟩ + t⟨−2, 3, 0⟩|⟨1/7, 0, 9/7⟩ + t⟨3, 3, 2⟩|⟨−2, 3, 0⟩ + t⟨5, −7, 3⟩','The point (−2, 3, 0) satisfies both plane equations. Cross the normals: ⟨1, 2, 3⟩ × ⟨−2, −1, 1⟩ = ⟨5, −7, 3⟩. This provides the direction in choice F.')
add('s2025',10,'vectors','Find the orthogonal projection of u = 4i + j + 2k onto v = i − j + k.','(5/21)(4i + j + 2k)|(5/3)(4i + j + 2k)|(5/21)(i − j + k)|(1/√3)(i − j + k)|(5/3)(i − j + k)|(1/√3)(4i + j + 2k)','The projection is [(u·v)/(v·v)]v. Here u·v = 4 − 1 + 2 = 5 and v·v = 3, so the projection is (5/3)(i − j + k).')
add('s2025',11,'chain','Suppose f(x, y, z) = eˣ(y + z), with x, y, z functions of s and t. At s = t = 0: x = 0, x<sub>t</sub> = 2, y = 1, y<sub>t</sub> = 3, z = 2, z<sub>t</sub> = 4. Find ∂f/∂t there.','13|9|6|24|0|11','Use f<sub>t</sub> = eˣ(y + z)x<sub>t</sub> + eˣy<sub>t</sub> + eˣz<sub>t</sub>. At the stated values, eˣ = 1, so f<sub>t</sub> = (1 + 2)·2 + 3 + 4 = 13.')
add('s2025',12,'tangent','Find the tangent plane to the elliptic cone y² + 4z² = x² at (5, 3, −2).','5x − y − 4z = 30|5x − 3y − 8z = 32|5x − 3y + 8z = 0|5x + 3y − 2z = 38|x + 3y − 2z = 18|x − y − 4z = 10','For F = x² − y² − 4z², the gradient at (5, 3, −2) is ⟨10, −6, 16⟩. Divide by 2 and write 5(x − 5) − 3(y − 3) + 8(z + 2) = 0. The constants cancel, leaving 5x − 3y + 8z = 0.')
